+// Sites (kitchens). Each location belongs to one site; batches, stock and
+// stock-takes are seen per site through their location. Items, suppliers,
+// recipes and dishes are shared by every site.
+import { AppError } from "../errors.js";
+
+/** The site every request uses when it names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Ids of the locations in a site. */
+export function siteLocations(store, site) {
+  return store.data.locations.filter((l) => l.site === site).map((l) => l.id);
+}
+
+/** Whether a batch is in `site` (always true when `site` is undefined: every site). */
+export function inSite(store, batch, site) {
+  return site === undefined || store.data.locations.some((l) => l.id === batch.location && l.site === site);
+}
