+++ b/tests/sites.test.js
@@ -0,0 +1,89 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+// Receives a one-line order of milk into the annex fridge.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", headers: annex, body: { supplierId: 2, lines: [{ itemId: 2, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send`, headers: annex });
+  return handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: annex, body: { lots: [{ lot: "AX-1", expires: "2026-10-29", location: "annex-fridge" }] } });
+}
+
+test("requests without the header see site main", async () => {
+  const { handle } = app();
+  const withHeader = await handle({ path: "/items", headers: { "x-larder-site": "main" } });
+  const without = await handle({ path: "/items" });
+  assert.deepEqual(withHeader.body, without.body);
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("stock, batches, value and alerts only see the request's site", async () => {
+  const { handle } = app();
+  const empty = (await handle({ path: "/items", headers: annex })).body;
+  assert.ok(empty.length > 0 && empty.every((i) => i.onHand === 0));
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+
+  const mainMilk = (await handle({ path: "/items/2" })).body.onHand;
+  const received = await stockAnnex(handle);
+  assert.equal(received.status, 200);
+  assert.equal((await handle({ path: "/items/2", headers: annex })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, mainMilk);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 3 * 129);
+  const alerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.lot), ["AX-1"]);
+  assert.ok(alerts.lowStock.some((i) => i.itemId === 2));
+});
+
+test("orders are received only into the request's site", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 4, qty: 1 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "x", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("cooking and waste only use the request's site", async () => {
+  const { handle, store } = app();
+  const before = JSON.stringify(store.data.batches);
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 1 } });
+  assert.equal(cook.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+  const waste = await handle({ method: "POST", path: "/batches/6/waste", headers: annex, body: { qty: 0.5 } });
+  assert.equal(waste.status, 404);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle } = app();
+  const wrong = await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "dry" } });
+  assert.equal(wrong.status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex })).status, 404);
+  const own = await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } });
+  assert.equal(own.status, 201);
+  const count = await handle({ method: "POST", path: `/stocktakes/${own.body.id}/counts`, headers: annex, body: { batchId: 6, counted: 1 } });
+  assert.equal(count.status, 404);
+});
+
+test("the nightly job checks every site", async () => {
+  const { handle, store } = app();
+  await stockAnnex(handle);
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const keys = store.data.outbox.map((m) => m.key);
+  assert.ok(keys.includes("expiry:2026-10-28:4"));
+  assert.ok(!keys.includes("low:2026-10-28"));
+  assert.ok(keys.includes("low:annex:2026-10-28"));
+  assert.ok(store.data.outbox.some((m) => m.subject.includes("AX-1")));
+});
